 public function __construct(public EnrollmentTransitionAccess $access){}
 public function roster(Request $r,int $section):array{[$sid]=$this->access->context($r);$s=$this->access->section($r,$section);$rows=DB::table('enrollments as e')->join('students as p','p.id','=','e.student_id')->where('e.school_id',$sid)->where('e.section_id',$section)->whereIn('e.status',['active','completed'])->where('p.status','active')->orderBy('p.admission_no')->orderBy('e.id')->get(['e.id as source_enrollment_id','e.student_id','e.starts_on','e.ends_on','e.status','e.roll_no','p.admission_no','p.first_name','p.last_name']);$processed=DB::table('enrollment_transition_events')->where('school_id',$sid)->whereIn('source_enrollment_id',$rows->pluck('source_enrollment_id'))->pluck('source_enrollment_id')->all();foreach($rows as $row)$row->processed=in_array($row->source_enrollment_id,$processed,true);return ['section'=>$s,'rows'=>$rows];}
 private function peak($rows,string $from,string $to):int{$events=[];foreach($rows as $e){$start=max($from,$e->starts_on);$end=min($to,$e->ends_on??$to);if($start>$end)continue;$events[$start]=($events[$start]??0)+1;if($end<$to){$next=CarbonImmutable::parse($end)->addDay()->toDateString();$events[$next]=($events[$next]??0)-1;}}ksort($events);$n=$peak=0;foreach($events as $delta){$n+=$delta;$peak=max($peak,$n);}return $peak;}
 public function calculate(Request $r,int $id):array{[$sid]=$this->access->context($r);$b=$this->access->batch($r,$id);$source=$this->access->section($r,$b->source_section_id);$session=$this->access->row('academic_sessions',$sid,$b->target_session_id);$items=DB::table('enrollment_transition_items')->where('school_id',$sid)->where('batch_id',$id)->orderBy('source_enrollment_id')->get();$global=[];$rows=[];$targets=[];$inputs=['batch'=>get_object_vars($b),'source'=>get_object_vars($source),'session'=>get_object_vars($session),'rows'=>[],'targets'=>[]];unset($inputs['batch']['snapshot'],$inputs['batch']['confirmed_digest']);if($b->effective_on>$this->access->today())$global[]='This is a future plan. Confirm on or after its effective date.';if($b->kind==='promotion'&&($session->id===$source->academic_session_id||$session->starts_on<=$source->session_end))$global[]='Promotion needs a later, non-overlapping academic session.';if($b->kind==='transfer'&&$session->id!==$source->academic_session_id)$global[]='A transfer stays within the source academic session.';
  foreach($items as $item){$en=$this->access->row('enrollments',$sid,$item->source_enrollment_id);abort_unless($en->section_id===$source->id,404);$student=$this->access->row('students',$sid,$en->student_id);$errors=[];$warnings=[];$target=null;$closing=min($source->session_end,$en->ends_on??$source->session_end,CarbonImmutable::parse($b->effective_on)->subDay()->toDateString());$in=['item'=>get_object_vars($item),'enrollment'=>get_object_vars($en),'student'=>['id'=>$student->id,'status'=>$student->status,'admitted_on'=>$student->admitted_on,'admission_no'=>$student->admission_no,'first_name'=>$student->first_name,'last_name'=>$student->last_name]];
   if($item->decision!=='hold'){
    if($student->status!=='active'||!in_array($en->status,['active','completed'],true))$errors[]='Student/source enrollment is no longer eligible.';
    if($closing<$en->starts_on||$b->effective_on<=$en->starts_on)$errors[]='Effective date must follow the enrollment start and preserve at least one source day.';
    $used=DB::table('enrollment_transition_events')->where('school_id',$sid)->where('source_enrollment_id',$en->id)->exists();$in['processed']=$used;if($used)$errors[]='This source enrollment was already processed.';
    $other=DB::table('enrollments')->where('school_id',$sid)->where('student_id',$student->id)->where('id','<>',$en->id)->where('status','active')->orderBy('id')->get();$in['other_active']=$other->all();if($other->isNotEmpty())$errors[]='Another active enrollment needs review before this decision.';
    $attendance=DB::table('attendance_records as a')->join('attendance_sessions as d','d.id','=','a.attendance_session_id')->where('a.school_id',$sid)->where('a.enrollment_id',$en->id)->where('d.attendance_date','>',$closing)->exists();$results=DB::table('test_results as r')->join('tests as t','t.id','=','r.test_id')->where('r.school_id',$sid)->where('r.enrollment_id',$en->id)->where('t.test_date','>',$closing)->exists();$in['later_attendance']=$attendance;$in['later_results']=$results;if($attendance||$results)$errors[]='Attendance/results after the proposed source closing date must be reviewed first.';
    $futureInvoices=DB::table('invoices')->where('school_id',$sid)->where('enrollment_id',$en->id)->where('status','<>','void')->where('period','>',$closing)->count();$in['future_invoices']=$futureInvoices;if($futureInvoices)$warnings[]='Future-dated invoices remain on the old enrollment. Review billing separately; nothing is cancelled or moved.';
    if($b->kind==='transfer'&&!in_array($item->decision,['transfer','withdraw'],true))$errors[]='A transfer batch supports transfer, withdraw or hold.';
    if($b->kind==='promotion'&&!in_array($item->decision,['promote','repeat','graduate','withdraw'],true))$errors[]='Choose promote, repeat, graduate, withdraw or hold.';
    if(in_array($item->decision,['promote','repeat','transfer'],true)){
     if(!$item->target_section_id)$errors[]='Choose the destination section.';else{$target=$this->access->section($r,$item->target_section_id);if($target->id===$source->id)$errors[]='Choose a different section.';if($target->academic_session_id!==$session->id)$errors[]='Destination belongs to a different target session.';if($target->session_status!=='active'||$target->campus_status!=='active')$errors[]='Destination session and campus must be active.';if($b->effective_on<$target->session_start||$b->effective_on>$target->session_end||$target->session_end<$this->access->today())$errors[]='Effective date must be inside a current or future destination session.';if($item->decision==='promote'&&$target->class_position<=$source->class_position)$errors[]='Promotion requires a higher class position.';if($item->decision==='repeat'&&$target->class_id!==$source->class_id)$errors[]='Repeat keeps the same class in the new session.';
      $overlap=DB::table('enrollments')->where('school_id',$sid)->where('student_id',$student->id)->where('id','<>',$en->id)->where('starts_on','<=',$target->session_end)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$b->effective_on))->orderBy('id')->get();$in['overlaps']=$overlap->all();if($overlap->isNotEmpty())$errors[]='Destination dates overlap another enrollment history.';
      if(!isset($targets[$target->id])){$existing=DB::table('enrollments')->where('school_id',$sid)->where('section_id',$target->id)->where('starts_on','<=',$target->session_end)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$b->effective_on))->orderBy('id')->get(['id','student_id','starts_on','ends_on','roll_no','status']);$targets[$target->id]=['section'=>$target,'existing'=>$existing,'incoming'=>[],'rolls'=>[]];}$targets[$target->id]['incoming'][]=$item->id;
      if($item->roll_no!==null){$fold=strtolower(trim($item->roll_no));if(isset($targets[$target->id]['rolls'][$fold])){$errors[]='A roll number is duplicated within this batch destination.';$targets[$target->id]['rolls'][$fold][]=$item->id;}else $targets[$target->id]['rolls'][$fold]=[$item->id];if(DB::table('enrollments')->where('school_id',$sid)->where('section_id',$target->id)->where('starts_on','<=',$target->session_end)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$b->effective_on))->whereRaw('TRIM(roll_no) = ?',[$item->roll_no])->exists())$errors[]='This roll number is already used during the destination date range.';}
      $warnings[]='Review the new fee plan and concessions separately; they are not copied.';
     }
    }else{if($item->target_section_id||$item->roll_no)$errors[]='Terminal decisions cannot create a destination enrollment or roll number.';if($item->decision==='graduate'&&$b->effective_on<=$source->session_end)$errors[]='Graduation takes effect after the source session ends.';}
    if($item->decision!=='promote'&&mb_strlen(trim($item->reason??''))<5)$errors[]='Add an individual reason of at least five characters for this decision.';
   }
   $rows[]=['item_id'=>$item->id,'source_enrollment_id'=>$en->id,'student_id'=>$student->id,'admission_no'=>$student->admission_no,'name'=>trim($student->first_name.' '.$student->last_name),'decision'=>$item->decision,'target_section_id'=>$item->target_section_id,'target_label'=>$target?($target->campus_name.' · '.$target->class_name.' '.$target->name):null,'roll_no'=>$item->roll_no,'reason'=>$item->reason,'closes_on'=>$closing,'starts_on'=>$target?$b->effective_on:null,'ends_on'=>$target?->session_end,'errors'=>$errors,'warnings'=>$warnings,'before'=>get_object_vars($en)];$inputs['rows'][]=$in;
  }
  $capacity=[];foreach($targets as $target){$s=$target['section'];$peak=$this->peak($target['existing'],$b->effective_on,$s->session_end);$after=$peak+count($target['incoming']);$capacity[]=['section_id'=>$s->id,'label'=>$s->campus_name.' · '.$s->class_name.' '.$s->name,'capacity'=>$s->capacity,'existing_peak'=>$peak,'incoming'=>count($target['incoming']),'projected_peak'=>$after];$inputs['targets'][]=['section'=>get_object_vars($s),'existing'=>$target['existing']->all()];foreach($rows as &$row)if(in_array($row['item_id'],$target['incoming'],true)){if($s->capacity!==null&&$after>$s->capacity)$row['errors'][]='Destination capacity would be exceeded.';if($row['roll_no']!==null&&count($target['rolls'][strtolower(trim($row['roll_no']))]??[])>1)$row['errors'][]='A roll number is duplicated within this batch destination.';}unset($row);}
  $counts=['hold'=>0,'promote'=>0,'repeat'=>0,'graduate'=>0,'withdraw'=>0,'transfer'=>0,'blocked'=>0];foreach($rows as &$row){$row['errors']=array_values(array_unique($row['errors']));$counts[$row['decision']]++;if($row['errors'])$counts['blocked']++;}unset($row);$changed=count($rows)-$counts['hold'];if(!$changed)$global[]='Choose at least one non-hold decision before confirmation.';
  return ['batch'=>$b,'source'=>$source,'target_session'=>$session,'rows'=>$rows,'capacity'=>$capacity,'counts'=>$counts,'blockers'=>$global,'can_apply'=>$b->status==='draft'&&!$global&&!$counts['blocked'],'source_digest'=>hash('sha256',json_encode($inputs)),'calculated_on'=>$this->access->today()];
 }
}
